import{_ as o,C as n,c as r,o as i,a3 as s,G as a}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Manage users","description":"","frontmatter":{},"headers":[],"relativePath":"master/general-settings/users/manage-users.md","filePath":"master/general-settings/users/manage-users.md","lastUpdated":1793074831000}'),l={name:"master/general-settings/users/manage-users.md"};function h(p,e,g,u,c,m){const t=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=s('<h1 id="manage-users" tabindex="-1">Manage users <a class="header-anchor" href="#manage-users" aria-label="Permalink to &quot;Manage users&quot;">​</a></h1><p>The <strong>Manage Users</strong> page sets the rules for how people join and sign in. You choose whether users can invite others and reset passwords. You also choose the role and company that new users receive.</p><blockquote><p><strong>In simple words:</strong> This page controls how new users are invited and what they get by default.</p></blockquote><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Create a <a href="./../companies/companies.html">company</a> and a <a href="./roles.html">role</a> first. You choose them as defaults below.</p></div><h2 id="open-the-page" tabindex="-1">Open the page <a class="header-anchor" href="#open-the-page" aria-label="Permalink to &quot;Open the page&quot;">​</a></h2><ol><li>Go to <code>Settings → Settings</code>.</li><li>In the left menu, under <strong>General</strong>, click <strong>Manage Users</strong>.</li></ol>',6)),a(t,{src:"/images1/general-settings/manage_users_page.png",alt:"Manage Users page with the four options"}),e[1]||(e[1]=s('<h2 id="set-the-options" tabindex="-1">Set the options <a class="header-anchor" href="#set-the-options" aria-label="Permalink to &quot;Set the options&quot;">​</a></h2><p>The page has four options.</p><ul><li><strong><em>Enable User Invitation:</em></strong> Turn on to let users invite other users. The <strong>Invite User</strong> button then shows on the Users list. When it is off, create users yourself with <strong>New User</strong>. See <a href="./users.html">Users</a>.</li><li><strong><em>Enable Reset Password:</em></strong> Turn on to let users reset their password. <ul><li>It shows the <strong>Change Password</strong> action on a user record.</li><li>It shows the reset link on the sign-in page.</li></ul></li><li><strong><em>Default Role:</em></strong> Choose the role given to a new user who accepts an invitation. Type to search the list.</li><li><strong><em>Default Company:</em></strong> Choose the company given to a new user who accepts an invitation. Type to search the list.</li></ul><p>Click <strong>Save changes</strong> to apply your choices.</p>',4)),a(t,{src:"/images1/general-settings/manage_users_saved.png",alt:"Manage Users page after saving, with the success message"}),e[2]||(e[2]=s('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Set <strong>Default Company</strong> before you invite anyone. Without it, <strong>Invite User</strong> shows the message <strong>Default Company Not Set</strong> and sends nothing.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Pick a role with limited access as <strong>Default Role</strong>. You can change a user&#39;s role later on their record.</p></div><h2 id="what-happens-next" tabindex="-1">What happens next <a class="header-anchor" href="#what-happens-next" aria-label="Permalink to &quot;What happens next&quot;">​</a></h2><p>When you click <strong>Invite User</strong> on the Users list, you enter an email address. The person receives a message with a link. After they accept, the account uses your default role and company.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./users.html">Users</a></li><li><a href="./roles.html">Roles</a></li><li><a href="./../companies/companies.html">Companies</a></li><li><a href="./../">General settings overview</a></li></ul>',6))])}const f=o(l,[["render",h]]);export{_ as __pageData,f as default};
